/bin/bash -lc "cat > /workspace/openai_client.py <<'EOF'
\"\"\"Minimal OpenAI Responses API client using only the Python standard library.

Prompts are sent with "'``store=False`` so OpenAI does not retain the response,
and the module never logs or writes prompts to disk. The API key is read from
the ``OPENAI_API_KEY`` environment variable (or passed explicitly).
"""

import json
import os
import sys
import urllib.error
import urllib.request

DEFAULT_BASE_URL = "https://api.openai.com/v1"
DEFAULT_MODEL = "gpt-4.1-mini"


class OpenAIError(Exception):
    def __init__(self, message, status=None):
        super().__init__(message)
        self.status = status


class OpenAIClient:
    def __init__(self, api_key=None, model=DEFAULT_MODEL, base_url=None, timeout=60):
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise OpenAIError("No API key: set OPENAI_API_KEY or pass api_key=")
        self.model = model
        self.base_url = (base_url or os.environ.get("OPENAI_BASE_URL") or DEFAULT_BASE_URL).rstrip("/")
        self.timeout = timeout

    def create_response(self, prompt, instructions=None, model=None, store=False, **extra):
        """POST /responses and return the parsed JSON body."""
        payload = {"model": model or self.model, "input": prompt, "store": store}
        if instructions:
            payload["instructions"] = instructions
        payload.update(extra)

        request = urllib.request.Request(
            self.base_url + "/responses",
            data=json.dumps(payload).encode("utf-8"),
            headers={
                "Authorization": "Bearer " + self.api_key,
                "Content-Type": "application/json",
            },
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                return json.loads(response.read().decode("utf-8"))
        except urllib.error.HTTPError as error:
            body = error.read().decode("utf-8", errors="replace")
            try:
                message = json.loads(body)["error"]["message"]
            except (ValueError, KeyError, TypeError):
                message = body or error.reason
            raise OpenAIError("HTTP %d: %s" % (error.code, message), status=error.code) from None
        except urllib.error.URLError as error:
            raise OpenAIError("Network error: %s" % error.reason) from None

    @staticmethod
    def extract_text(response):
        """Concatenate all output_text parts from a Responses API result."""
        parts = []
        for item in response.get("output", []):
            if item.get("type") == "message":
                for content in item.get("content", []):
                    if content.get("type") == "output_text":
                        parts.append(content.get("text", ""))
        return "".join(parts)

    def ask(self, prompt, **kwargs):
        """Send a prompt and return the reply text."""
        return self.extract_text(self.create_response(prompt, **kwargs))


def ask(prompt, **kwargs):
    client_args = {key: kwargs.pop(key) for key in ("api_key", "base_url", "timeout") if key in kwargs}
    return OpenAIClient(**client_args).ask(prompt, **kwargs)


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    prompt = " ".join(argv) if argv else sys.stdin.read()
    if not prompt.strip():
        print("usage: openai_client.py [prompt...]  (or pipe prompt on stdin)", file=sys.stderr)
        return 2
    try:
        print(ask(prompt))
    except OpenAIError as error:
        print("error: %s" % error, file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
